package main

const knowledgeHTML = `<details id="knowledge-panel" class="card workspace-panel" role="tabpanel" aria-labelledby="knowledge-panel-tab" data-workspace-panel="models" hidden><summary>研究知識與擷取規則</summary><div class="section-heading"><h2>研究知識與擷取規則</h2><p>檢視研究反思，管理可還原的知識與資料擷取版本。</p></div><p>每輪保存成效與策略版本；比較多輪結果後確認試用，並持續觀察與回復。來源取得率不等於資料可信度。</p><button id="knowledge-refresh" type="button" class="ghost">更新研究知識</button><div id="reflection-list" class="cards"></div><div id="knowledge-list" class="cards"></div><details><summary>新增知識版本</summary><form id="knowledge-form"><label>類型<select name="kind"><option>SOURCE_RELIABILITY</option><option>RESEARCH_STRATEGY</option><option>ENDPOINT_PATTERN</option><option>AUTH_PATTERN</option><option>DISCOVERY_PATH</option><option>MODEL_ALIAS_RULE</option><option>VERIFICATION_OUTCOME</option><option>PROVIDER_RECIPE</option></select></label><label>對象<input name="subject" maxlength="240" required></label><label>資料 JSON<textarea name="data" required></textarea></label><label>已保存證據 ID（逗號分隔）<input name="evidence_ids" required></label><label>判斷理由<textarea name="reason" maxlength="1000" required></textarea></label><button>保存知識提案</button></form></details>` + connectorDiscoveryHTML + `<details><summary>宣告式資料擷取</summary><p>指定唯讀 GET 與 JSON 欄位對照。測試通過後可確認啟用。</p><div id="connector-list" class="cards"></div><form id="connector-form"><label>Provider<select name="provider_id" id="connector-provider" required></select></label><label>規則名稱<input name="name" maxlength="120" value="quota" required></label><label>資料種類<select name="kind"><option>QUOTA</option><option>PRICING</option><option>BALANCE</option><option>USAGE</option><option>PERFORMANCE</option><option>NOTICE</option><option>CATALOG</option></select></label><label>端點 Path<input name="path" placeholder="/v1/quota" required></label><label>憑證用途<select name="credential_role"><option>INFERENCE</option><option>ACCOUNT_PAT</option><option>NONE</option></select></label><label>PAT 參照 ID（僅帳戶資料需要）<input name="pat_credential_id"></label><label>資料範圍<select name="scope"><option>MODEL_KEY_GROUP</option><option>MODEL_PROVIDER</option><option>ACCOUNT</option><option>CATALOG</option></select></label><label>清單 JSON Pointer<input name="root_pointer" placeholder="/data"></label><label>欄位對照 JSON<textarea name="fields" required placeholder='{"model_id":"/model","group":"/group","rpd":"/limits/rpd","tpd":"/limits/tpd"}'></textarea></label><label>單位<select name="unit"><option>REQUESTS</option><option>TOKENS</option><option>USD/1M tokens</option><option>USD/1K tokens</option><option>USD/token</option><option>USD</option><option>CREDITS</option><option>MS</option><option>TPS</option><option>NONE</option></select></label><label class="check"><input name="fixed_charge_absent" type="checkbox">定價證據明確沒有固定請求費</label><label>判斷理由<textarea name="reason" maxlength="1000" required></textarea></label><button>保存擷取草稿</button></form></details></details>`

const jsKnowledge = `
let knowledgeVersions=[],connectorVersions=[],knowledgeLoadVersion=0;
async function loadKnowledge(){const ticket=++knowledgeLoadVersion,panels=["reflection-list","knowledge-list","connector-list","connector-discovery-list"].map($);panels.forEach(p=>{p.setAttribute("aria-busy","true");p.querySelectorAll(".item-button").forEach(b=>b.disabled=true);});try{const [reflections,knowledge,connectors,discoveries]=await Promise.all([api("/research/reflections"),api("/research/knowledge"),api("/connectors"),api("/connectors/discoveries")]);if(ticket!==knowledgeLoadVersion)return;knowledgeVersions=knowledge;connectorVersions=connectors;renderConnectorDiscoveries(discoveries);const reports=$("reflection-list"),rules=$("knowledge-list"),profiles=$("connector-list");reports.replaceChildren();rules.replaceChildren();profiles.replaceChildren();reflections.slice(0,15).forEach(r=>item(reports,"研究反思 · "+r.report.status,new Date(r.at).toLocaleString()+" · "+r.report.http_requests+" 次 HTTP",()=>{const box=modal("本輪研究成效");factsView(box,"來源、語言、查詢與驗證",r.report);box.append(el("p","反思參照："+r.id));}));knowledge.slice(0,100).forEach(v=>item(rules,v.kind+" · v"+v.version,(v.active?"已啟用":"待判讀")+" · "+v.subject,()=>knowledgeDetail(v)));connectors.forEach(v=>item(profiles,(v.discovery?(connectorKindLabels[v.config.kind]||v.config.kind):v.name)+" · v"+v.version,(v.active?"已啟用 · ":"")+(connectorStatusLabels[v.status]||v.status)+" · "+v.config.path,()=>connectorDetail(v)));if(!reports.children.length)item(reports,"還沒有反思","完成一輪研究後會保存成效。");if(!rules.children.length)item(rules,"還沒有知識提案","可以由 Assistant 根據保存的證據提出。");const select=$("connector-provider"),old=select.value;select.replaceChildren();providers.forEach(p=>option(select,p.id,p.name));if([...select.options].some(n=>n.value===old))select.value=old;}finally{if(ticket===knowledgeLoadVersion)panels.forEach(p=>{p.removeAttribute("aria-busy");p.querySelectorAll(".item-button").forEach(b=>b.disabled=false);});}}
function knowledgeEvaluationLabel(status){return {POLICY_CHANGED:"需重新評估",READY_FOR_TRIAL:"可確認試用",INSUFFICIENT:"比較資料不足",REGRESSION:"發現退步",SOURCE_CHANGED:"來源版本已變",DEGRADED:"研究成效下降",OBSERVED:"持續觀察中",NO_BASELINE:"尚無比較基線"}[status]||status;}
function knowledgeDetail(v){
 const box=modal(({SOURCE_RELIABILITY:"來源優先序",RESEARCH_STRATEGY:"搜尋策略"}[v.kind]||v.kind)+" · v"+v.version),scoped=!!v.data.scope_hash,measurable=["SOURCE_RELIABILITY","RESEARCH_STRATEGY"].includes(v.kind);let busy=false,needsReload=false;
 box.append(el("p",v.reason),el("p",v.active?"此版本目前已啟用":"此版本尚未啟用"));
 const run=async callback=>{if(busy||needsReload)return;busy=true;const controls=[...box.querySelectorAll("button,input,textarea")].map(n=>[n,n.disabled]);controls.forEach(([n])=>n.disabled=true);try{await callback();}finally{busy=false;if(!needsReload)controls.forEach(([n,disabled])=>{if(n.isConnected)n.disabled=disabled;});}};
 const reload=async(message,reopen=true)=>{try{await loadKnowledge();if(reopen){const current=knowledgeVersions.find(x=>x.id===v.id);if(current)knowledgeDetail(current);}else $("detail").close();notice(message);}catch(e){needsReload=true;box.querySelectorAll("button,input,textarea").forEach(n=>n.disabled=true);const recovery=el("div",undefined,"card");recovery.append(el("p","操作已保存，畫面尚未更新。重新讀取後再進行下一項操作。","error"));box.prepend(recovery);const retry=action(recovery,"重新讀取研究版本",async()=>{await loadKnowledge();const current=knowledgeVersions.find(x=>x.id===v.id);if(current)knowledgeDetail(current);});retry.focus();notice("操作已保存，請重新讀取版本",true);}};
 const guardedAction=(label,callback,ghost=true)=>{const button=el("button",label,ghost?"ghost":"");button.type="button";button.addEventListener("click",async()=>{try{await run(callback);}catch(e){notice(e.message,true);}});box.append(button);return button;};
 if(measurable){
  box.append(el("h3","策略評估"));
  if(v.evaluation){const e=v.evaluation,t=e.target_observations;box.append(el("p",knowledgeEvaluationLabel(e.status)+" · "+t.runs+" 輪同範圍研究 · "+t.http_requests+" 次 HTTP"),el("p",e.reason));Object.entries(e.diff||{}).forEach(([name,d])=>box.append(el("p",({weight:"研究權重",priority:"語言優先序",query:"搜尋查詢"}[name]||name)+"："+String(d.before??"尚無")+" → "+String(d.after))));box.append(el("p","比較基線："+(e.baseline_id||"內建策略")+"；歷史排序效益 "+e.baseline_replay.utility.toFixed(2)+" → "+e.proposed_replay.utility.toFixed(2)));const details=el("details"),summary=el("summary","比較範圍、證據與限制");details.append(summary);factsView(details,"已保存評估",e);box.append(details);}
  else box.append(el("p",scoped?"先比較多輪本機研究與目前策略，再確認試用。":"這是手動優先序提案。可先評估；尚無比較資料時不視為已改善。"));
  if(v.status!=="IMPORTED")guardedAction("評估這個提案",async()=>{notice("正在比較研究策略…");await submit("/research/knowledge/evaluate",{id:v.id});await reload("研究策略評估已保存");});
 }
 if(v.monitor){const m=v.monitor;box.append(el("h3","啟用後的實際研究"),el("p",knowledgeEvaluationLabel(m.status)+" · "+m.observed.runs+" 輪 · "+m.observed.http_requests+" 次 HTTP"),el("p",m.reason));factsView(box,"實際使用版本的觀測",m);}
 factsView(box,"知識與依據",v);
 const form=el("form"),input=field(form,"修訂資料 JSON","textarea",JSON.stringify(v.data,null,2)),reason=field(form,"修訂理由","textarea");reason.required=true;form.append(el("button","保存新版本"));box.append(form);
 form.addEventListener("submit",async e=>{e.preventDefault();try{await run(async()=>{notice("正在保存知識…");await submit("/research/knowledge",{kind:v.kind,subject:v.subject,data:JSON.parse(input.value),reason:reason.value,evidence_ids:v.evidence_ids});await reload("知識新版本已保存",false);});}catch(e){notice(e.message,true);}});
 if(!v.active&&v.status!=="IMPORTED"){
  const ready=!scoped||(v.evaluation?.status==="READY_FOR_TRIAL"&&v.evaluation.baseline_id===(v.active_id||""));
  const activate=guardedAction(scoped?"確認試用此知識版本":"確認啟用此知識版本",async()=>{notice("正在啟用知識…");const result=await submit("/research/knowledge/activate",{id:v.id,expected_active_id:v.active_id||"",evaluation_id:v.evaluation?.status==="READY_FOR_TRIAL"?v.evaluation.id:"",confirm:true});await reload("知識版本已啟用",false);if(!needsReload){const undo=el("div",undefined,"actions");$("knowledge-list").prepend(undo);action(undo,"Undo 知識啟用",async()=>{notice("正在還原知識…");await submit("/versions/undo",{id:result.action_id,confirm:true});await loadKnowledge();notice("知識啟用已還原");});}},false);activate.disabled=!ready;box.insertBefore(activate,form);
 }
 if(v.active&&v.activation_action_id){const rollback=guardedAction("回復啟用前版本",async()=>{await submit("/versions/undo",{id:v.activation_action_id,confirm:true});await reload("已回復啟用前版本");});box.insertBefore(rollback,form);}
}


function bindKnowledge(){bindConnectorDiscovery();$("knowledge-panel").addEventListener("toggle",()=>{if($("knowledge-panel").open)loadKnowledge().catch(e=>notice(e.message,true));});$("knowledge-refresh").addEventListener("click",()=>loadKnowledge().catch(e=>notice(e.message,true)));$("knowledge-form").addEventListener("submit",async e=>{e.preventDefault();const v=data(e.target);try{await submit("/research/knowledge",{kind:v.kind,subject:v.subject,data:JSON.parse(v.data),evidence_ids:v.evidence_ids.split(",").map(s=>s.trim()).filter(Boolean),reason:v.reason});await loadKnowledge();notice("知識提案已保存");}catch(e){notice(e.message,true);}});$("connector-form").addEventListener("submit",async e=>{e.preventDefault();const v=data(e.target);try{await submit("/connectors",{provider_id:v.provider_id,name:v.name,reason:v.reason,config:{kind:v.kind,path:v.path,credential_role:v.credential_role,pat_credential_id:v.pat_credential_id,scope:v.scope,root_pointer:v.root_pointer,fields:JSON.parse(v.fields),unit:v.unit,fixed_charge_absent:e.target.elements.fixed_charge_absent.checked}});await loadKnowledge();notice("擷取草稿已保存，請先測試");}catch(e){notice(e.message,true);}});}
`
